819	/* Classify an Agent reply text into a coarse card category so the
820	 * left color bar gives a glanceable cue.  Matching is intentionally
821	 * simple (case-insensitive substring) — this is a visual hint, not
822	 * a parser.  Returns the palette color for the matched category. */
823	static uint32_t chat_view_classify_reply(const char* text)
824	{
825	    if (!text || !*text) {
826	        return LVGL_UI_CARD_COLOR_PLAIN;
827	    }
828	
829	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
830	     * so substring checks are case-insensitive for the latin keywords. */
831	    char buf[LVGL_UI_MSG_MAX_LEN];
832	    size_t i;
833	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
834	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
835	    }
836	    buf[i] = '\0';
837	
838	    /* Conclusion: explicit yes/no or recommendation phrasing */
839	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
840	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
841	        strstr(buf, "\xe4\xb8\x8d\xe5\xbb\xba\xe8\xae\xae") /* 不建议 */ ||
842	        strstr(buf, "\xe5\xbb\xba\xe8\xae\xae") /* 建议 */ ) {
843	        return LVGL_UI_CARD_COLOR_CONCLUSION;
844	    }
845	
846	    /* Structured: Gerrit change status keywords (latin) or 状态: */
847	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
848	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
849	        return LVGL_UI_CARD_COLOR_STRUCTURED;
850	    }
851	
852	    /* Jira: workflow status or assignee fields */
853	    if (strstr(buf, "more info") || strstr(buf, "assignee") ||
854	        strstr(buf, "\xe7\xbb\x8f\xe5\x8a\x9e\xe4\xba\xba") /* 经办人 */ ||
855	        strstr(buf, "jira") ) {
856	        return LVGL_UI_CARD_COLOR_JIRA;
857	    }
858	
859	    return LVGL_UI_CARD_COLOR_PLAIN;
860	}
