58	/**
59	 * Calculate a safe allocation size based on available memory.
60	 * Returns a value between min_size and requested, scaled by
61	 * available free heap. Reserves AGENT_MEM_RESERVE_BYTES for
62	 * other subsystems.
63	 */
64	#define AGENT_MEM_RESERVE_BYTES (32 * 1024)
65	
66	static inline size_t agent_mem_safe_size(size_t requested, size_t min_size)
67	{
68	    agent_mem_status_t st;
69	    agent_mem_get_status(&st);
70	
71	    if (st.free_heap <= AGENT_MEM_RESERVE_BYTES)
72	        return min_size;
73	
74	    size_t available = st.free_heap - AGENT_MEM_RESERVE_BYTES;
75	    if (available >= requested)
76	        return requested;
77	    if (available >= min_size)
78	        return available;
79	    return min_size;
80	}
