43	/**
44	 * Check if HEARTBEAT.md has actionable content.
45	 * Returns true if any line is NOT:
46	 *   - empty / whitespace-only
47	 *   - a markdown header (starts with #)
48	 *   - a completed checkbox (- [x] or * [x])
49	 */
50	static bool heartbeat_has_tasks(void)
51	{
52	    FILE *f = fopen(AGENT_HEARTBEAT_FILE, "r");
53	    if (!f) {
54	        return false;
55	    }
56	
57	    char line[256];
58	    bool found_task = false;
59	
60	    while (fgets(line, sizeof(line), f)) {
61	        /* Skip leading whitespace */
62	        const char *p = line;
63	        while (*p && isspace((unsigned char)*p)) {
64	            p++;
65	        }
66	
67	        /* Skip empty lines */
68	        if (*p == '\0') {
69	            continue;
70	        }
71	
72	        /* Skip markdown headers */
73	        if (*p == '#') {
74	            continue;
75	        }
76	
77	        /* Skip completed checkboxes: "- [x]" or "* [x]" */
78	        if ((*p == '-' || *p == '*') && *(p + 1) == ' ' && *(p + 2) == '[') {
79	            char mark = *(p + 3);
80	            if ((mark == 'x' || mark == 'X') && *(p + 4) == ']') {
81	                continue;
82	            }
83	        }
84	
85	        /* Found an actionable line */
86	        found_task = true;
87	        break;
88	    }
89	
90	    fclose(f);
91	    return found_task;
92	}
