500	/****************************************************************************
501	 * Name: audio_fake_frame_delay
502	 *
503	 * Description: Delay the audio frame.
504	 *
505	 ****************************************************************************/
506	
507	static void audio_fake_frame_delay(FAR struct audio_fake_s *priv,
508	                                   FAR struct ap_buffer_s *apb)
509	{
510	  uint64_t total_time;
511	  uint64_t diff_time;
512	
513	  priv->total_bytes += apb->nbytes;
514	  total_time = (priv->total_bytes * 1000 * 1000) / priv->bps;
515	  diff_time = TICK2USEC(clock_systime_ticks() - priv->start_tick);
516	  if (diff_time >= total_time)
517	    {
518	      auderr("ERROR: diff_time %" PRIu64 " > total_time %" PRIu64 ".\n",
519	              diff_time, total_time);
520	    }
521	  else
522	    {
523	      nxsig_usleep(total_time - diff_time);
524	    }
525	}
