583	/****************************************************************************
584	 * Name: audio_fake_getcaps
585	 *
586	 * Description: Get the audio device capabilities
587	 *
588	 ****************************************************************************/
589	
590	static int audio_fake_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
591	                              FAR struct audio_caps_s *caps)
592	{
593	  FAR struct audio_fake_s *priv = (struct audio_fake_s *)dev;
594	
595	  audinfo("type=%d\n", type);
596	
597	  /* Validate the structure */
598	
599	  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));
600	
601	  /* Fill in the caller's structure based on requested info */
602	
603	  caps->ac_format.hw  = 0;
604	  caps->ac_controls.w = 0;
605	
606	  switch (caps->ac_type)
607	    {
608	      /* Caller is querying for the types of units we support */
609	
610	      case AUDIO_TYPE_QUERY:
611	
612	        /* Provide our overall capabilities.  The interfacing software
613	         * must then call us back for specific info for each capability.
614	         */
615	
616	        caps->ac_channels = (priv->params->channels[0] << 4) |
617	                            (priv->params->channels[1] & 0x0f);
618	
619	        switch (caps->ac_subtype)
620	          {
621	            case AUDIO_TYPE_QUERY:
622	
623	              /* The types of audio units we implement */
624	
625	              caps->ac_controls.b[0] = priv->params->playback ?
626	                                       AUDIO_TYPE_OUTPUT : AUDIO_TYPE_INPUT;
627	              caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
628	
629	              break;
630	
631	            case AUDIO_FMT_PCM:
632	
633	              caps->ac_controls.b[0] =
634	                  audio_fake_subfmt_convert(priv->params->format[0]);
635	              caps->ac_controls.b[1] =
636	                  audio_fake_subfmt_convert(priv->params->format[1]);
637	              caps->ac_controls.b[2] =
638	                  audio_fake_subfmt_convert(priv->params->format[2]);
639	              caps->ac_controls.b[3] =
640	                  audio_fake_subfmt_convert(priv->params->format[3]);
641	
642	              break;
643	
644	            default:
645	              caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
646	              break;
647	          }
648	
649	        break;
650	
651	      /* Provide capabilities of our OUTPUT unit */
652	
653	      case AUDIO_TYPE_OUTPUT:
654	      case AUDIO_TYPE_INPUT:
655	
656	        caps->ac_channels = (priv->params->channels[0] << 4) |
657	                            (priv->params->channels[1] & 0x0f);
658	
659	        switch (caps->ac_subtype)
660	          {
661	            case AUDIO_TYPE_QUERY:
662	
663	              caps->ac_channels = (priv->params->channels[0] << 4) |
664	                                  (priv->params->channels[1] & 0x0f);
665	
666	              /* Report the Sample rates we support */
667	
668	              caps->ac_controls.hw[0] =
669	                  audio_fake_samp_rate_convert(priv->params->samplerate[0]) |
670	                  audio_fake_samp_rate_convert(priv->params->samplerate[1]) |
671	                  audio_fake_samp_rate_convert(priv->params->samplerate[2]) |
672	                  audio_fake_samp_rate_convert(priv->params->samplerate[3]);
673	
674	              break;
675	
676	            default:
677	              break;
678	          }
679	
680	        break;
681	
682	      /* All others we don't support */
683	
684	      default:
685	
686	        /* Zero out the fields to indicate no support */
687	
688	        caps->ac_subtype  = 0;
689	        caps->ac_channels = 0;
690	
691	        break;
692	    }
693	
694	  /* Return the length of the audio_caps_s struct for validation of
695	   * proper Audio device type.
696	   */
697	
698	  audinfo("Return %d\n", caps->ac_len);
699	  return caps->ac_len;
700	}
