702	/****************************************************************************
703	 * Name: audio_fake_configure
704	 *
705	 * Description:
706	 *   Configure the audio device for the specified  mode of operation.
707	 *
708	 ****************************************************************************/
709	
710	#ifdef CONFIG_AUDIO_MULTI_SESSION
711	static int audio_fake_configure(FAR struct audio_lowerhalf_s *dev,
712	                                FAR void *session,
713	                                FAR const struct audio_caps_s *caps)
714	#else
715	static int audio_fake_configure(FAR struct audio_lowerhalf_s *dev,
716	                                FAR const struct audio_caps_s *caps)
717	#endif
718	{
719	  FAR struct audio_fake_s *priv = (FAR struct audio_fake_s *)dev;
720	  int ret;
721	  audinfo("ac_type: %d\n", caps->ac_type);
722	
723	  if (priv->mqname[0] == '\0')
724	    {
725	      struct mq_attr attr;
726	
727	      /* Create a message queue for the worker thread */
728	
729	      snprintf(priv->mqname, sizeof(priv->mqname), "/tmp/%" PRIXPTR,
730	               (uintptr_t)priv);
731	
732	      attr.mq_maxmsg  = 16;
733	      attr.mq_msgsize = sizeof(struct audio_msg_s);
734	      attr.mq_curmsgs = 0;
735	      attr.mq_flags   = 0;
736	
737	      ret = file_mq_open(&priv->mq, priv->mqname, O_RDWR | O_CREAT, 0644,
738	                         &attr);
739	      if (ret < 0)
740	        {
741	          /* Error creating message queue! */
742	
743	          auderr("ERROR: Couldn't allocate message queue\n");
744	          return ret;
745	        }
746	    }
747	
748	  /* Process the configure operation */
749	
750	  switch (caps->ac_type)
751	    {
752	      case AUDIO_TYPE_OUTPUT:
753	      case AUDIO_TYPE_INPUT:
754	        priv->sample_rate =
755	            caps->ac_controls.hw[0] | (caps->ac_controls.b[3] << 16);
756	        priv->channels = caps->ac_channels;
757	        priv->format   = caps->ac_controls.b[2];
758	        priv->bps = caps->ac_channels * priv->sample_rate *
759	                    priv->format / 8;
760	
761	        audinfo("Audio type: %s\n", (caps->ac_type == AUDIO_TYPE_OUTPUT)
762	                                        ? "AUDIO_TYPE_OUTPUT"
763	                                        : "AUDIO_TYPE_INPUT");
764	        audinfo("Number of channels: %u\n", caps->ac_channels);
765	        audinfo("Sample rate:        %u\n", caps->ac_controls.hw[0]);
766	        audinfo("Sample width:       %u\n", caps->ac_controls.b[2]);
767	        break;
768	
769	      default:
770	        audinfo("default case: %d\n", caps->ac_type);
771	        break;
772	    }
773	
774	  audinfo("Return OK\n");
775	  return OK;
776	}
