792	/****************************************************************************
793	 * Name: audio_fake_workerthread
794	 *
795	 *  This is the thread that feeds data to the chip and keeps the audio
796	 *  stream going.
797	 *
798	 ****************************************************************************/
799	
800	static int audio_fake_workerthread(int argc, FAR char **argv)
801	{
802	  FAR struct audio_fake_s *priv = (FAR struct audio_fake_s *)
803	                                  ((uintptr_t)strtoul(argv[1], NULL, 16));
804	  FAR struct ap_buffer_s *apb;
805	  struct audio_msg_s msg;
806	  struct mq_attr attr;
807	  unsigned int prio;
808	  int msglen;
809	  int ret;
810	
811	  audinfo("Entry\n");
812	
813	  /* Loop as long as we are supposed to be running */
814	
815	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
816	  while (!priv->terminate)
817	#else
818	  for (; ; )
819	#endif
820	    {
821	      /* Wait for messages from our message queue */
822	
823	      msglen = file_mq_receive(&priv->mq, (FAR char *)&msg,
824	                               sizeof(msg), &prio);
825	
826	      /* Handle the case when we return with no message */
827	
828	      if (msglen < sizeof(struct audio_msg_s))
829	        {
830	          auderr("ERROR: Message too small: %d\n", msglen);
831	          continue;
832	        }
833	
834	      /* Process the message */
835	
836	      switch (msg.msg_id)
837	        {
838	          case AUDIO_MSG_DATA_REQUEST:
839	            break;
840	
841	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
842	          case AUDIO_MSG_STOP:
843	
844	            /* Consume all buffers on the bufferq after stop */
845	
846	            for (; ; )
847	              {
848	                file_mq_getattr(&priv->mq, &attr);
849	                if (attr.mq_curmsgs == 0)
850	                  {
851	                    break;
852	                  }
853	
854	                file_mq_receive(&priv->mq, (FAR char *)&msg, sizeof(msg),
855	                                &prio);
856	
857	                /* direct dequeue buffer to application */
858	
859	                apb = (FAR struct ap_buffer_s *)msg.u.ptr;
860	#ifdef CONFIG_AUDIO_MULTI_SESSION
861	                priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
862	                                apb, OK, NULL);
863	#else
864	                priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
865	                                apb, OK);
866	#endif
867	              }
868	
869	            priv->terminate = true;
870	            break;
871	#endif
872	
873	          case AUDIO_MSG_ENQUEUE:
874	            apb = (FAR struct ap_buffer_s *)msg.u.ptr;
875	            ret = audio_fake_process_buffer(&priv->dev, apb);
876	            if (ret < 0)
877	              {
878	                auderr("fake audio process error %d\n", ret);
879	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
880	                priv->terminate = true;
881	#endif
882	              }
883	            break;
884	
885	          default:
886	            auderr("ERROR: Ignoring message ID %d\n", msg.msg_id);
887	            break;
888	        }
889	    }
890	
891	  /* Close the message queue */
892	
893	  file_mq_close(&priv->mq);
894	  file_mq_unlink(priv->mqname);
895	  priv->mqname[0] = '\0';
896	
897	  audio_fake_sin_data_deinit(&priv->dev);
898	  audio_fake_file_deinit(&priv->dev);
899	
900	#ifdef CONFIG_AUDIO_MULTI_SESSION
901	  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
902	#else
903	  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
904	#endif
905	  audinfo("Exit %s\n", priv->params->devname);
906	
907	  return OK;
908	}
