1060	static int audio_fake_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
1061	                                    FAR struct ap_buffer_s *apb)
1062	{
1063	  FAR struct audio_fake_s *priv = (FAR struct audio_fake_s *)dev;
1064	  struct audio_msg_s msg;
1065	  int ret;
1066	
1067	  DEBUGASSERT(priv && apb && priv->dev.upper);
1068	
1069	  audinfo("apb=%p curbyte=%d nbytes=%d\n", apb, apb->curbyte, apb->nbytes);
1070	
1071	  msg.msg_id = AUDIO_MSG_ENQUEUE;
1072	  msg.u.ptr  = apb;
1073	
1074	  ret = file_mq_send(&priv->mq, (FAR const char *)&msg, sizeof(msg),
1075	                     CONFIG_AUDIO_FAKE_MSG_PRIO);
1076	  if (ret < 0)
1077	    {
1078	      auderr("ERROR: file_mq_send failed: %d\n", ret);
1079	    }
1080	
1081	  audinfo("Return OK\n");
1082	  return ret;
1083	}
1084	
1085	/****************************************************************************
1086	 * Name: audio_fake_get_latency
1087	 *
1088	 * Description: calculate latency in frames.
1089	 *
1090	 ****************************************************************************/
1091	
1092	static int audio_fake_get_latency(struct audio_lowerhalf_s *dev,
1093	                                  unsigned long arg)
1094	{
1095	  int ret = OK;
1096	  FAR long *latency = (FAR long *)arg;
1097	#ifdef CONFIG_AUDIO_DRIVER_SPECIFIC_BUFFERS
1098	  FAR struct audio_fake_s *priv;
1099	  struct mq_attr attr;
1100	  uint32_t period_frames;
1101	
1102	  priv = (FAR struct audio_fake_s *)dev;
1103	
1104	  ret = file_mq_getattr(&priv->mq, &attr);
1105	  if (ret < 0)
1106	    {
1107	      *latency = 0;
1108	      auderr("failed to get mq attributes, error: %d\n", ret);
1109	      return ret;
1110	    }
1111	
1112	  period_frames = (priv->sample_rate * priv->params->period_time) / 1000;
1113	  *latency = attr.mq_curmsgs * period_frames;
1114	
1115	  audinfo("mq_curmsgs: %ld, period_frames: %"PRIu32"\n",
1116	          attr.mq_curmsgs, period_frames);
1117	#else
1118	  *latency = 0;
1119	  audinfo("AUDIOIOC_GETLATENCY not implemented\n");
1120	#endif
1121	
1122	  return ret;
1123	}
1124	
1125	/****************************************************************************
1126	 * Name: audio_fake_ioctl
1127	 *
1128	 * Description: Perform a device ioctl
1129	 *
1130	 ****************************************************************************/
1131	
1132	static int audio_fake_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
1133	                            unsigned long arg)
1134	{
1135	#ifdef CONFIG_AUDIO_DRIVER_SPECIFIC_BUFFERS
1136	  FAR struct audio_fake_s *priv = (FAR struct audio_fake_s *)dev;
1137	  FAR struct ap_buffer_info_s *bufinfo;
1138	#endif
1139	  int ret = OK;
1140	
1141	  audinfo("cmd=%d arg=%ld\n", cmd, arg);
1142	
1143	  /* Deal with ioctls passed from the upper-half driver */
1144	
1145	  switch (cmd)
1146	    {
1147	        /* Report our preferred buffer size and quantity */
1148	
1149	      case AUDIOIOC_GETBUFFERINFO:
1150	        {
1151	          audinfo("AUDIOIOC_GETBUFFERINFO:\n");
1152	#ifdef CONFIG_AUDIO_DRIVER_SPECIFIC_BUFFERS
1153	          bufinfo = (FAR struct ap_buffer_info_s *)arg;
1154	          bufinfo->buffer_size =
1155	              (priv->bps * priv->params->period_time) / 1000;
1156	          bufinfo->nbuffers = priv->params->periods;
1157	#else
1158	          audwarn("AUDIOIOC_GETBUFFERINFO Return EPERM\n");
1159	          return -EPERM;
1160	#endif
1161	        }
1162	        break;
1163	      case AUDIOIOC_GETLATENCY:
1164	        if (!dev || !arg)
1165	          {
1166	            auderr("invalid params dev: %p, arg: %lu.\n", dev, arg);
1167	            ret = -EINVAL;
1168	          }
1169	        else
1170	          {
1171	            ret = audio_fake_get_latency(dev, arg);
1172	          }
1173	        break;
1174	      default:
1175	        ret = -ENOTTY;
1176	        break;
1177	    }
1178	
1179	  audinfo("Return ret: %d\n", ret);
1180	  return ret;
1181	}
1182	
1183	/****************************************************************************
1184	 * Name: audio_fake_reserve
1185	 *
1186	 * Description: Reserves a session (the only one we have).
1187	 *
1188	 ****************************************************************************/
1189	
1190	#ifdef CONFIG_AUDIO_MULTI_SESSION
1191	static int audio_fake_reserve(FAR struct audio_lowerhalf_s *dev,
1192	                              FAR void **session)
1193	#else
1194	static int audio_fake_reserve(FAR struct audio_lowerhalf_s *dev)
1195	#endif
1196	{
1197	  FAR struct audio_fake_s *priv = (FAR struct audio_fake_s *)dev;
1198	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1199	  priv->terminate = false;
1200	#endif
1201	  audinfo("%s reserve\n", priv->params->devname);
1202	  return OK;
1203	}
1204	
1205	/****************************************************************************
1206	 * Name: audio_fake_release
1207	 *
1208	 * Description: Releases the session (the only one we have).
1209	 *
1210	 ****************************************************************************/
1211	
1212	#ifdef CONFIG_AUDIO_MULTI_SESSION
1213	static int audio_fake_release(FAR struct audio_lowerhalf_s *dev,
1214	                              FAR void *session)
1215	#else
1216	static int audio_fake_release(FAR struct audio_lowerhalf_s *dev)
1217	#endif
1218	{
1219	  return OK;
1220	}
1221	
1222	/****************************************************************************
1223	 * Public Functions
1224	 ****************************************************************************/
1225	
1226	/****************************************************************************
1227	 * Name: audio_fake_initialize
1228	 *
1229	 * Description:
1230	 *   Initialize and register fake audio device.
1231	 *
1232	 ****************************************************************************/
1233	
1234	int audio_fake_initialize(void)
1235	{
1236	  return audio_fake_register(g_devparams, nitems(g_devparams));
1237	}
1238	
1239	/****************************************************************************
1240	 * Name: audio_fake_register
1241	 *
1242	 * Description:
1243	 *   Register audio driver nodes using fake_server
1244	 *
1245	 * Input Parameters:
1246	 *   params - fake audio parameters array
1247	 *   nparams - number of fake audio parameters
1248	 *
1249	 * Returned Value:
1250	 *   >0 values represents the number of node register succeed;
1251	 *   <0 values indicate that all nodes have failed to register, and
1252	 *   the value is the error code of the last node register returned.
1253	 *
1254	 ****************************************************************************/
1255	
1256	int audio_fake_register(FAR const audio_fake_params_t *params,
1257	                        size_t nparams)
1258	{
1259	  FAR struct audio_fake_s *priv;
1260	  FAR audio_fake_params_t *param;
1261	  size_t good = 0;
1262	  size_t i;
1263	  int ret = 0;
1264	
1265	  if (!params || !nparams)
1266	    {
1267	      auderr("ERROR: Invalid fake audio parameters\n");
1268	      return -EINVAL;
1269	    }
1270	
1271	  for (i = 0; i < nparams; i++)
1272	    {
1273	      priv = (FAR struct audio_fake_s *)kmm_zalloc(sizeof(*priv));
1274	      if (!priv)
1275	        {
1276	          auderr("ERROR: Failed to allocate fake audio priv\n");
1277	          ret = -ENOMEM;
1278	          continue;
1279	        }
1280	
1281	      param = (FAR audio_fake_params_t *)kmm_zalloc(sizeof(*param));
1282	      if (!param)
1283	        {
1284	          auderr("ERROR: Failed to allocate fake audio params\n");
1285	          ret = -ENOMEM;
1286	          kmm_free(priv);
1287	          continue;
1288	        }
1289	
1290	      *param = params[i];
1291	      priv->dev.ops = &g_audioops;
1292	      priv->params  = param;
1293	
1294	      ret = audio_register(param->devname, &priv->dev);
1295	      if (ret < 0)
1296	        {
1297	          audwarn("WARNING: Failed to register (%s) fake audio device(%d)\n",
1298	                  params->devname, ret);
1299	          kmm_free(priv);
1300	          kmm_free(param);
1301	          continue;
1302	        }
1303	
1304	      good++;
1305	    }
1306	
1307	  return good ? good : ret;
1308	}
