#include <driver/aud_dac.h>
#include <driver/aud_dac_types.h>
#include <driver/gpio.h>
#include <driver/gpio_types.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define AUD_INFO(fmt, ...) audinfo("BK7258: " fmt "\n", ##__VA_ARGS__)
#define AUD_ERR(fmt, ...)  auderr("BK7258 ERROR: " fmt "\n", ##__VA_ARGS__)

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

/* audio_ops_s callbacks */

static int bk7258_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
                          FAR struct audio_caps_s *caps);

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR void *session,
                            FAR const struct audio_caps_s *caps);
#else
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR const struct audio_caps_s *caps);
#endif

static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev);

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
                        FAR void *session);
#else
static int bk7258_start(FAR struct audio_lowerhalf_s *dev);
#endif

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
#  ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
                       FAR void *session);
#  else
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev);
#  endif
#endif

static int bk7258_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                FAR struct ap_buffer_s *apb);

static int bk7258_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
                        unsigned long arg);

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_reserve(FAR struct audio_lowerhalf_s *dev,
                          FAR void **session);
#else
static int bk7258_reserve(FAR struct audio_lowerhalf_s *dev);
#endif

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_release(FAR struct audio_lowerhalf_s *dev,
                          FAR void *session);
#else
static int bk7258_release(FAR struct audio_lowerhalf_s *dev);
#endif

/* Internal functions */

static int bk7258_worker_thread(int argc, FAR char **argv);
static void bk7258_pa_control(bool enable);
static int bk7258_adc_init(FAR struct bk7258_audio_s *priv);
static int bk7258_dac_init(FAR struct bk7258_audio_s *priv);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct audio_ops_s g_bk7258_playback_ops =
{
  bk7258_getcaps,       /* getcaps        */
  bk7258_configure,     /* configure      */
  bk7258_shutdown,      /* shutdown       */
  bk7258_start,         /* start          */
#ifndef CONFIG_AUDIO_EXCLUDE_STOP
  bk7258_stop,          /* stop           */
#endif
  NULL,                 /* pause          */
  NULL,                 /* resume         */
  NULL,                 /* allocbuffer    */
  NULL,                 /* freebuffer     */
  bk7258_enqueuebuffer, /* enqueuebuffer  */
  NULL,                 /* cancelbuffer   */
  bk7258_ioctl,         /* ioctl          */
  NULL,                 /* read           */
  NULL,                 /* write          */
  bk7258_reserve,       /* reserve        */
  bk7258_release        /* release        */
};

static const struct audio_ops_s g_bk7258_capture_ops =
{
  bk7258_getcaps,       /* getcaps        */
  bk7258_configure,     /* configure      */
  bk7258_shutdown,      /* shutdown       */
  bk7258_start,         /* start          */
#ifndef CONFIG_AUDIO_EXCLUDE_STOP
  bk7258_stop,          /* stop           */
#endif
  NULL,                 /* pause          */
  NULL,                 /* resume         */
  NULL,                 /* allocbuffer    */
  NULL,                 /* freebuffer     */
  bk7258_enqueuebuffer, /* enqueuebuffer  */
  NULL,                 /* cancelbuffer   */
  bk7258_ioctl,         /* ioctl          */
  NULL,                 /* read           */
  NULL,                 /* write          */
  bk7258_reserve,       /* reserve        */
  bk7258_release        /* release        */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_pa_control
 *
 * Description: Control the Power Amplifier (PA) enable/disable via GPIO.
 *
 ****************************************************************************/

static void bk7258_pa_control(bool enable)
{
  int gpio = BK7258_AUDIO_PA_GPIO;
  int level = enable ? BK7258_AUDIO_PA_ON_LEVEL :
                       (1 - BK7258_AUDIO_PA_ON_LEVEL);

  AUD_INFO("PA %s (GPIO %d, level %d)",
           enable ? "ON" : "OFF", gpio, level);

  bk_gpio_set_output(gpio, level);

  if (enable)
    {
      nxsig_usleep(BK7258_AUDIO_PA_ON_DELAY_MS * 1000);
    }
  else
    {
      nxsig_usleep(BK7258_AUDIO_PA_OFF_DELAY_MS * 1000);
    }
}

/****************************************************************************
 * Name: bk7258_adc_init
 *
 * Description: Initialize the ADC for audio capture.
 *
 ****************************************************************************/

static int bk7258_adc_init(FAR struct bk7258_audio_s *priv)
{
  aud_adc_config_t cfg = DEFAULT_AUD_ADC_CONFIG();

  AUD_INFO("ADC init: rate=%"PRIu32" ch=%d bps=%d gain=0x%x",
           priv->sample_rate, priv->channels, priv->bpsamp,
           priv->gain);

  /* Configure ADC */

  cfg.samp_rate = priv->sample_rate;
  cfg.adc_gain = priv->gain;

  /* Set channel mode based on channel count */

  if (priv->channels == 2)
    {
      cfg.adc_chl = AUD_ADC_CHL_LR;
    }
  else
    {
      cfg.adc_chl = AUD_ADC_CHL_L;
    }

  /* Initialize ADC */

  bk_aud_adc_init(&cfg);

  /* Set sample rate explicitly */

  bk_aud_adc_set_samp_rate(priv->sample_rate);

  return OK;
}

/****************************************************************************
 * Name: bk7258_dac_init
 *
 * Description: Initialize the DAC for audio playback.
 *
 ****************************************************************************/

static int bk7258_dac_init(FAR struct bk7258_audio_s *priv)
{
  aud_dac_config_t cfg = DEFAULT_AUD_DAC_CONFIG();

  AUD_INFO("DAC init: rate=%"PRIu32" ch=%d bps=%d gain=0x%x",
           priv->sample_rate, priv->channels, priv->bpsamp,
           priv->gain);

  /* Configure DAC */

  cfg.samp_rate = priv->sample_rate;
  cfg.dac_gain = priv->gain;

  /* Set channel mode based on channel count */

  if (priv->channels == 2)
    {
      cfg.dac_chl = AUD_DAC_CHL_LR;
    }
  else
    {
      cfg.dac_chl = AUD_DAC_CHL_L;
    }

  /* Initialize DAC */

  bk_aud_dac_init(&cfg);

  /* Set sample rate explicitly */

  bk_aud_dac_set_samp_rate(priv->sample_rate);

  return OK;
}

/****************************************************************************
 * Name: bk7258_getcaps
 *
 * Description: Get the audio device capabilities.
 *
 ****************************************************************************/

static int bk7258_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
                          FAR struct audio_caps_s *caps)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;

  AUD_INFO("getcaps type=%d", type);

  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));

  caps->ac_format.hw = 0;
  caps->ac_controls.w = 0;

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_QUERY:
        {
          caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);

          switch (caps->ac_subtype)
            {
              case AUDIO_TYPE_QUERY:
                {
                  /* Report device type */

                  if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
                    {
                      caps->ac_controls.b[0] = AUDIO_TYPE_OUTPUT;
                    }
                  else
                    {
                      caps->ac_controls.b[0] = AUDIO_TYPE_INPUT;
                    }

                  caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
                }
                break;

              case AUDIO_FMT_PCM:
                {
                  /* Report supported PCM sub-formats */

                  caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
                }
                break;

              default:
                caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
                break;
            }
        }
        break;

      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        {
          caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);

          switch (caps->ac_subtype)
            {
              case AUDIO_TYPE_QUERY:
                {
                  /* Report supported sample rates */

                  caps->ac_controls.hw[0] =
                    AUDIO_SAMP_RATE_8K |
                    AUDIO_SAMP_RATE_16K |
                    AUDIO_SAMP_RATE_44K |
                    AUDIO_SAMP_RATE_48K;
                }
                break;

              default:
                break;
            }
        }
        break;

      default:
        {
          caps->ac_subtype  = 0;
          caps->ac_channels = 0;
        }
        break;
    }

  return caps->ac_len;
}

/****************************************************************************
 * Name: bk7258_configure
 *
 * Description: Configure the audio device for the specified mode of
 *              operation.
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR void *session,
                            FAR const struct audio_caps_s *caps)
#else
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR const struct audio_caps_s *caps)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  int ret = OK;

  AUD_INFO("configure ac_type=%d", caps->ac_type);

  /* Create message queue if not yet created */

  if (priv->mqname[0] == '\0')
    {
      struct mq_attr attr;

      snprintf(priv->mqname, sizeof(priv->mqname), "/tmp/bk7258_%p",
               priv);

      attr.mq_maxmsg  = BK7258_AUDIO_MSG_MAX;
      attr.mq_msgsize = sizeof(struct audio_msg_s);
      attr.mq_curmsgs = 0;
      attr.mq_flags   = 0;

      ret = file_mq_open(&priv->mq, priv->mqname,
                         O_RDWR | O_CREAT, 0644, &attr);
      if (ret < 0)
        {
          AUD_ERR("Failed to create message queue: %d", ret);
          return ret;
        }
    }

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        {
          /* Extract configuration from capabilities */

          priv->sample_rate = caps->ac_controls.hw[0] |
                              ((uint32_t)caps->ac_controls.b[3] << 16);
          priv->channels = caps->ac_channels;
          priv->bpsamp = caps->ac_controls.b[2];

          /* Default to 16-bit if not specified */

          if (priv->bpsamp == 0)
            {
              priv->bpsamp = 16;
            }

          /* Default to 16kHz if not specified */

          if (priv->sample_rate == 0)
            {
              priv->sample_rate = 16000;
            }

          /* Default to 2 channels if not specified */

          if (priv->channels == 0)
            {
              priv->channels = 2;
            }

          AUD_INFO("Configured: rate=%"PRIu32" ch=%d bps=%d",
                   priv->sample_rate, priv->channels, priv->bpsamp);
        }
        break;

      default:
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: bk7258_shutdown
 *
 * Description: Shutdown the driver and put it in the lowest power state.
 *
 ****************************************************************************/

static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;

  AUD_INFO("shutdown");

  /* Close message queue if open */

  if (priv->mqname[0] != '\0')
    {
      file_mq_close(&priv->mq);
      file_mq_unlink(priv->mqname);
      priv->mqname[0] = '\0';
    }

  /* Deinitialize hardware */

  if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
    {
      bk7258_pa_control(false);
      bk_aud_dac_stop();
      bk_aud_dac_deinit();
    }
  else
    {
      bk_aud_adc_stop();
      bk_aud_adc_deinit();
    }

  return OK;
}

/****************************************************************************
 * Name: bk7258_start
 *
 * Description: Start the configured operation (audio streaming).
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
                        FAR void *session)
#else
static int bk7258_start(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  FAR char *argv[2];
  char arg1[32];
  int ret;

  AUD_INFO("start");

  if (priv->running)
    {
      AUD_ERR("Already running");
      return -EPERM;
    }

  /* Initialize hardware */

  if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
    {
      ret = bk7258_dac_init(priv);
      if (ret < 0)
        {
          AUD_ERR("DAC init failed: %d", ret);
          return ret;
        }

      /* Enable PA before starting playback */

      bk7258_pa_control(true);

      /* Start DAC */

      bk_aud_dac_start();
    }
  else
    {
      ret = bk7258_adc_init(priv);
      if (ret < 0)
        {
          AUD_ERR("ADC init failed: %d", ret);
          return ret;
        }

      /* Start ADC */

      bk_aud_adc_start();
    }

  priv->terminate = false;
  priv->running = true;

  /* Start worker thread */

  AUD_INFO("Starting worker thread");

  snprintf(arg1, sizeof(arg1), "%p", priv);
  argv[0] = arg1;
  argv[1] = NULL;

  ret = kthread_create("bk7258_audio",
                       BK7258_AUDIO_WORKER_PRIORITY,
                       BK7258_AUDIO_WORKER_STACKSIZE,
                       bk7258_worker_thread, argv);
  if (ret < 0)
    {
      AUD_ERR("Failed to create worker thread: %d", ret);
      priv->running = false;

      if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
        {
          bk7258_pa_control(false);
          bk_aud_dac_stop();
          bk_aud_dac_deinit();
        }
      else
        {
          bk_aud_adc_stop();
          bk_aud_adc_deinit();
        }

      return ret;
    }

  priv->worker_pid = ret;
  AUD_INFO("Worker thread started (pid=%d)", ret);

  return OK;
}

/****************************************************************************
 * Name: bk7258_stop
 *
 * Description: Stop the configured operation (audio streaming).
 *
 ****************************************************************************/

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
                       FAR void *session)
#else
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  struct audio_msg_s term_msg;

  AUD_INFO("stop");

  if (!priv->running)
    {
      return OK;
    }

  /* Send stop message to worker thread */

  priv->terminate = true;

  term_msg.msg_id = AUDIO_MSG_STOP;
  term_msg.u.data = 0;

  file_mq_send(&priv->mq, (FAR const char *)&term_msg, sizeof(term_msg),
               BK7258_AUDIO_MSG_PRIO);

  /* Wait for worker thread to finish (with timeout) */

  int timeout = 50;
  while (priv->running && timeout-- > 0)
    {
      nxsig_usleep(10000);  /* 10ms */
    }

  /* Force cleanup if thread didn't exit */

  if (priv->running)
    {
      AUD_ERR("Worker thread did not exit, forcing cleanup");
      priv->running = false;
    }

  /* Stop hardware */

  if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
    {
      bk_aud_dac_stop();
      bk_aud_dac_deinit();
      bk7258_pa_control(false);
    }
  else
    {
      bk_aud_adc_stop();
      bk_aud_adc_deinit();
    }

  AUD_INFO("stop complete");

  return OK;
}
#endif

/****************************************************************************
 * Name: bk7258_enqueuebuffer
 *
 * Description: Enqueue an Audio Pipeline Buffer for processing.
 *
 ****************************************************************************/

static int bk7258_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                FAR struct ap_buffer_s *apb)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  struct audio_msg_s msg;
  int ret;

  DEBUGASSERT(priv && apb && priv->dev.upper);

  msg.msg_id = AUDIO_MSG_ENQUEUE;
  msg.u.ptr  = apb;

  ret = file_mq_send(&priv->mq, (FAR const char *)&msg, sizeof(msg),
                     BK7258_AUDIO_MSG_PRIO);
  if (ret < 0)
    {
      AUD_ERR("file_mq_send failed: %d", ret);
    }

  return ret;
}

/****************************************************************************
 * Name: bk7258_ioctl
 *
 * Description: Perform a device ioctl.
 *
 ****************************************************************************/

static int bk7258_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
                        unsigned long arg)
{
  int ret = OK;

  AUD_INFO("ioctl cmd=%d arg=%lu", cmd, arg);

  switch (cmd)
    {
      case AUDIOIOC_GETBUFFERINFO:
        {
          FAR struct ap_buffer_info_s *bufinfo =
            (FAR struct ap_buffer_info_s *)arg;

          bufinfo->nbuffers = BK7258_AUDIO_NUM_BUFFERS;
          bufinfo->buffer_size = BK7258_AUDIO_BUFFER_SIZE;
        }
        break;

      default:
        ret = -ENOTTY;
        break;
    }

  return ret;
}

