/****************************************************************************
 * Name: bk7258_worker_thread
 *
 * Description: Worker thread for processing audio buffers.
 *   - Playback: reads buffers from queue and writes to DAC
 *   - Capture: reads from ADC and fills buffers, then dequeues
 *
 ****************************************************************************/

static int bk7258_worker_thread(int argc, FAR char **argv)
{
  FAR struct bk7258_audio_s *priv =
    (FAR struct bk7258_audio_s *)((uintptr_t)strtoul(argv[1], NULL, 16));
  FAR struct ap_buffer_s *apb;
  struct audio_msg_s msg;
  struct mq_attr attr;
  unsigned int prio;
  int msglen;
  int ret;

  AUD_INFO("Worker thread entry (type=%s)",
           priv->type == BK7258_AUDIO_TYPE_PLAYBACK ? "playback" : "capture");

  while (!priv->terminate)
    {
      /* Wait for messages from the message queue */

      msglen = file_mq_receive(&priv->mq, (FAR char *)&msg,
                               sizeof(msg), &prio);

      if (msglen < sizeof(struct audio_msg_s))
        {
          if (priv->terminate)
            {
              break;
            }

          AUD_ERR("Message too small: %d", msglen);
          continue;
        }

      switch (msg.msg_id)
        {
          case AUDIO_MSG_ENQUEUE:
            {
              apb = (FAR struct ap_buffer_s *)msg.u.ptr;

              if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
                {
                  /* Playback: write buffer data to DAC */

                  if (apb->nbytes > 0 && apb->curbyte < apb->nbytes)
                    {
                      uint8_t *data = &apb->samp[apb->curbyte];
                      uint32_t remaining = apb->nbytes - apb->curbyte;

                      ret = bk_aud_dac_write((char *)data, remaining);
                      if (ret < 0)
                        {
                          AUD_ERR("DAC write failed: %d", ret);
                        }
                    }
                }
              else
                {
                  /* Capture: read data from ADC into buffer */

                  if (apb->nmaxbytes > 0)
                    {
                      uint32_t total_read = 0;
                      uint32_t to_read = apb->nmaxbytes;

                      while (total_read < to_read && !priv->terminate)
                        {
                          uint32_t chunk = to_read - total_read;
                          if (chunk > 1024)
                            {
                              chunk = 1024;
                            }

                          ret = bk_aud_adc_get_fifo_data(
                            (char *)&apb->samp[total_read], chunk);
                          if (ret > 0)
                            {
                              total_read += ret;
                            }
                          else if (ret == 0)
                            {
                              /* No data available, wait a bit */

                              nxsig_usleep(1000);
                            }
                          else
                            {
                              AUD_ERR("ADC read error: %d", ret);
                              break;
                            }
                        }

                      apb->nbytes = total_read;
                      apb->curbyte = 0;
                      apb->flags = 0;
                    }
                }

              /* Dequeue the buffer back to upper half */

#ifdef CONFIG_AUDIO_MULTI_SESSION
              priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                              apb, OK, NULL);
#else
              priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                              apb, OK);
#endif
            }
            break;

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
          case AUDIO_MSG_STOP:
            {
              /* Drain remaining buffers */

              for (; ; )
                {
                  file_mq_getattr(&priv->mq, &attr);
                  if (attr.mq_curmsgs == 0)
                    {
                      break;
                    }

                  file_mq_receive(&priv->mq, (FAR char *)&msg,
                                  sizeof(msg), &prio);

                  apb = (FAR struct ap_buffer_s *)msg.u.ptr;
#ifdef CONFIG_AUDIO_MULTI_SESSION
                  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                                  apb, OK, NULL);
#else
                  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                                  apb, OK);
#endif
                }

              priv->terminate = true;
            }
            break;
#endif

          default:
            AUD_ERR("Unknown message ID %d", msg.msg_id);
            break;
        }
    }

  /* Clean up */

  file_mq_close(&priv->mq);
  file_mq_unlink(priv->mqname);
  priv->mqname[0] = '\0';

  priv->running = false;

#ifdef CONFIG_AUDIO_MULTI_SESSION
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
#else
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
#endif

  AUD_INFO("Worker thread exit");

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_audio_playback_initialize
 *
 * Description:
 *   Initialize and register the BK7258 playback audio device as
 *   /dev/audio/pcm0p
 *
 ****************************************************************************/

int bk7258_audio_playback_initialize(void)
{
  FAR struct bk7258_audio_s *priv;
  int ret;

  AUD_INFO("Initializing playback device");

  priv = kmm_zalloc(sizeof(struct bk7258_audio_s));
  if (!priv)
    {
      AUD_ERR("Failed to allocate playback device");
      return -ENOMEM;
    }

  priv->dev.ops = &g_bk7258_playback_ops;
  priv->type = BK7258_AUDIO_TYPE_PLAYBACK;
  priv->sample_rate = BK7258_AUDIO_DEFAULT Samp_RATE;
  priv->channels = BK7258_AUDIO_DEFAULT_CHANNELS;
  priv->bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
  priv->gain = BK7258_AUDIO_DEFAULT_GAIN;
  priv->running = false;
  priv->terminate = false;
  priv->mqname[0] = '\0';

  ret = audio_register("pcm0p", &priv->dev);
  if (ret < 0)
    {
      AUD_ERR("Failed to register playback device: %d", ret);
      kmm_free(priv);
      return ret;
    }

  AUD_INFO("Playback device registered as /dev/audio/pcm0p");
  return OK;
}

/****************************************************************************
 * Name: bk7258_audio_capture_initialize
 *
 * Description:
 *   Initialize and register the BK7258 capture audio device as
 *   /dev/audio/pcm0c
 *
