 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <sys/param.h>

#include <assert.h>
#include <debug.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>

#include <nuttx/audio/audio.h>
#include <nuttx/audio/bk7258_audio.h>
#include <nuttx/kmalloc.h>
#include <nuttx/mqueue.h>
#include <nuttx/signal.h>
#include <nuttx/kthread.h>
#include <nuttx/fs/fs.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define AUD_INFO(fmt, ...) audinfo("BK7258: " fmt "\n", ##__VA_ARGS__)
#define AUD_ERR(fmt, ...)  auderr("BK7258 ERROR: " fmt "\n", ##__VA_ARGS__)

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

/* audio_ops_s callbacks */

static int bk7258_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
                          FAR struct audio_caps_s *caps);

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR void *session,
                            FAR const struct audio_caps_s *caps);
#else
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR const struct audio_caps_s *caps);
#endif

static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev);

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
                        FAR void *session);
#else
static int bk7258_start(FAR struct audio_lowerhalf_s *dev);
#endif

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
#  ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
                       FAR void *session);
#  else
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev);
#  endif
#endif

static int bk7258_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                FAR struct ap_buffer_s *apb);

static int bk7258_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
                        unsigned long arg);

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_reserve(FAR struct audio_lowerhalf_s *dev,
                          FAR void **session);
#else
static int bk7258_reserve(FAR struct audio_lowerhalf_s *dev);
#endif

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_release(FAR struct audio_lowerhalf_s *dev,
                          FAR void *session);
#else
static int bk7258_release(FAR struct audio_lowerhalf_s *dev);
#endif

/* Internal functions */

static int bk7258_worker_thread(int argc, FAR char **argv);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct audio_ops_s g_bk7258_playback_ops =
{
  bk7258_getcaps,       /* getcaps        */
  bk7258_configure,     /* configure      */
  bk7258_shutdown,      /* shutdown       */
  bk7258_start,         /* start          */
#ifndef CONFIG_AUDIO_EXCLUDE_STOP
  bk7258_stop,          /* stop           */
#endif
  NULL,                 /* pause          */
  NULL,                 /* resume         */
  NULL,                 /* allocbuffer    */
  NULL,                 /* freebuffer     */
  bk7258_enqueuebuffer, /* enqueuebuffer  */
  NULL,                 /* cancelbuffer   */
  bk7258_ioctl,         /* ioctl          */
  NULL,                 /* read           */
  NULL,                 /* write          */
  bk7258_reserve,       /* reserve        */
  bk7258_release        /* release        */
};

static const struct audio_ops_s g_bk7258_capture_ops =
{
  bk7258_getcaps,       /* getcaps        */
  bk7258_configure,     /* configure      */
  bk7258_shutdown,      /* shutdown       */
  bk7258_start,         /* start          */
#ifndef CONFIG_AUDIO_EXCLUDE_STOP
  bk7258_stop,          /* stop           */
#endif
  NULL,                 /* pause          */
  NULL,                 /* resume         */
  NULL,                 /* allocbuffer    */
  NULL,                 /* freebuffer     */
  bk7258_enqueuebuffer, /* enqueuebuffer  */
  NULL,                 /* cancelbuffer   */
  bk7258_ioctl,         /* ioctl          */
  NULL,                 /* read           */
  NULL,                 /* write          */
  bk7258_reserve,       /* reserve        */
  bk7258_release        /* release        */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_getcaps
 *
 * Description: Get the audio device capabilities.
 *
 ****************************************************************************/

static int bk7258_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
                          FAR struct audio_caps_s *caps)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;

  AUD_INFO("getcaps type=%d", type);

  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));

  caps->ac_format.hw = 0;
  caps->ac_controls.w = 0;

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_QUERY:
        {
          caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);

          switch (caps->ac_subtype)
            {
              case AUDIO_TYPE_QUERY:
                {
                  /* Report device type */

                  if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
                    {
                      caps->ac_controls.b[0] = AUDIO_TYPE_OUTPUT;
                    }
                  else
                    {
                      caps->ac_controls.b[0] = AUDIO_TYPE_INPUT;
                    }

                  caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
                }
                break;

              case AUDIO_FMT_PCM:
                {
                  /* Report supported PCM sub-formats */

                  caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
                }
                break;

              default:
                caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
                break;
            }
        }
        break;

      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        {
          caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);

          switch (caps->ac_subtype)
            {
              case AUDIO_TYPE_QUERY:
                {
                  /* Report supported sample rates */

                  caps->ac_controls.hw[0] =
                    AUDIO_SAMP_RATE_8K |
                    AUDIO_SAMP_RATE_16K |
                    AUDIO_SAMP_RATE_44K |
                    AUDIO_SAMP_RATE_48K;
                }
                break;

              default:
                break;
            }
        }
        break;

      default:
        {
          caps->ac_subtype  = 0;
          caps->ac_channels = 0;
        }
        break;
    }

  return caps->ac_len;
}

/****************************************************************************
 * Name: bk7258_configure
 *
 * Description: Configure the audio device for the specified mode of
 *              operation.
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR void *session,
                            FAR const struct audio_caps_s *caps)
#else
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR const struct audio_caps_s *caps)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  int ret = OK;

  AUD_INFO("configure ac_type=%d", caps->ac_type);

  /* Create message queue if not yet created */

  if (priv->mqname[0] == '\0')
    {
      struct mq_attr attr;

      snprintf(priv->mqname, sizeof(priv->mqname), "/tmp/bk7258_%p",
               priv);

      attr.mq_maxmsg  = BK7258_AUDIO_MSG_MAX;
      attr.mq_msgsize = sizeof(struct audio_msg_s);
      attr.mq_curmsgs = 0;
      attr.mq_flags   = 0;

      ret = file_mq_open(&priv->mq, priv->mqname,
                         O_RDWR | O_CREAT, 0644, &attr);
      if (ret < 0)
        {
          AUD_ERR("Failed to create message queue: %d", ret);
          return ret;
        }
    }

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        {
          /* Extract configuration from capabilities */

          priv->sample_rate = caps->ac_controls.hw[0] |
                              ((uint32_t)caps->ac_controls.b[3] << 16);
          priv->channels = caps->ac_channels;
          priv->bpsamp = caps->ac_controls.b[2];

          /* Default to 16-bit if not specified */

          if (priv->bpsamp == 0)
            {
              priv->bpsamp = 16;
            }

          /* Default to 16kHz if not specified */

          if (priv->sample_rate == 0)
            {
              priv->sample_rate = 16000;
            }

          /* Default to 2 channels if not specified */

          if (priv->channels == 0)
            {
              priv->channels = 2;
            }

          AUD_INFO("Configured: rate=%"PRIu32" ch=%d bps=%d",
                   priv->sample_rate, priv->channels, priv->bpsamp);
        }
        break;

      default:
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: bk7258_shutdown
 *
 * Description: Shutdown the driver and put it in the lowest power state.
 *
 ****************************************************************************/

static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;

  AUD_INFO("shutdown");

  /* Close message queue if open */

  if (priv->mqname[0] != '\0')
    {
      file_mq_close(&priv->mq);
      file_mq_unlink(priv->mqname);
      priv->mqname[0] = '\0';
    }

  return OK;
}

/****************************************************************************
 * Name: bk7258_start
 *
 * Description: Start the configured operation (audio streaming).
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
                        FAR void *session)
#else
static int bk7258_start(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  FAR char *argv[2];
  char arg1[32];
  int ret;

  AUD_INFO("start");

  if (priv->running)
    {
      AUD_ERR("Already running");
      return -EPERM;
    }

  priv->terminate = false;
  priv->running = true;

  /* Start worker thread */

  AUD_INFO("Starting worker thread");

  snprintf(arg1, sizeof(arg1), "%p", priv);
  argv[0] = arg1;
  argv[1] = NULL;

  ret = kthread_create("bk7258_audio",
                       BK7258_AUDIO_WORKER_PRIORITY,
                       BK7258_AUDIO_WORKER_STACKSIZE,
                       bk7258_worker_thread, argv);
  if (ret < 0)
    {
      AUD_ERR("Failed to create worker thread: %d", ret);
      priv->running = false;
      return ret;
    }

  priv->worker_pid = ret;
  AUD_INFO("Worker thread started (pid=%d)", ret);

  return OK;
}

/****************************************************************************
 * Name: bk7258_stop
 *
 * Description: Stop the configured operation (audio streaming).
 *
 ****************************************************************************/

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
                       FAR void *session)
#else
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  struct audio_msg_s term_msg;

  AUD_INFO("stop");

  if (!priv->running)
    {
      return OK;
    }

  /* Send stop message to worker thread */

  priv->terminate = true;

  term_msg.msg_id = AUDIO_MSG_STOP;
  term_msg.u.data = 0;

  file_mq_send(&priv->mq, (FAR const char *)&term_msg, sizeof(term_msg),
               BK7258_AUDIO_MSG_PRIO);

  /* Wait for worker thread to finish (with timeout) */

  int timeout = 50;
  while (priv->running && timeout-- > 0)
    {
      nxsig_usleep(10000);  /* 10ms */
    }

  /* Force cleanup if thread didn't exit */

  if (priv->running)
    {
      AUD_ERR("Worker thread did not exit, forcing cleanup");
      priv->running = false;
    }

  AUD_INFO("stop complete");

  return OK;
}
#endif

/****************************************************************************
 * Name: bk7258_enqueuebuffer
 *
 * Description: Enqueue an Audio Pipeline Buffer for processing.
 *
 ****************************************************************************/

static int bk7258_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                FAR struct ap_buffer_s *apb)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  struct audio_msg_s msg;
  int ret;

  DEBUGASSERT(priv && apb && priv->dev.upper);

  msg.msg_id = AUDIO_MSG_ENQUEUE;
  msg.u.ptr  = apb;

  ret = file_mq_send(&priv->mq, (FAR const char *)&msg, sizeof(msg),
                     BK7258_AUDIO_MSG_PRIO);
  if (ret < 0)
    {
      AUD_ERR("file_mq_send failed: %d", ret);
    }

  return ret;
}

/****************************************************************************
 * Name: bk7258_ioctl
 *
 * Description: Perform a device ioctl.
 *
 ****************************************************************************/

static int bk7258_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
                        unsigned long arg)
{
  int ret = OK;

  AUD_INFO("ioctl cmd=%d arg=%lu", cmd, arg);

  switch (cmd)
    {
      case AUDIOIOC_GETBUFFERINFO:
        {
          FAR struct ap_buffer_info_s *bufinfo =
            (FAR struct ap_buffer_info_s *)arg;

          bufinfo->nbuffers = BK7258_AUDIO_NUM_BUFFERS;
          bufinfo->buffer_size = BK7258_AUDIO_BUFFER_SIZE;
        }
        break;

      default:
        ret = -ENOTTY;
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: bk7258_reserve
 *
 * Description: Reserves a session.
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_reserve(FAR struct audio_lowerhalf_s *dev,
                          FAR void **session)
#else
static int bk7258_reserve(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  AUD_INFO("reserve");
  priv->terminate = false;
  return OK;
}

/****************************************************************************
 * Name: bk7258_release
 *
 * Description: Releases the session.
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_release(FAR struct audio_lowerhalf_s *dev,
                          FAR void *session)
#else
static int bk7258_release(FAR struct audio_lowerhalf_s *dev)
#endif
{
  AUD_INFO("release");
  return OK;
}

/****************************************************************************
 * Name: bk7258_worker_thread
 *
 * Description: Worker thread for processing audio buffers.
 *   - Playback: reads buffers from queue and writes to DAC
 *   - Capture: reads from ADC and fills buffers, then dequeues
 *
 ****************************************************************************/

static int bk7258_worker_thread(int argc, FAR char **argv)
{
  FAR struct bk7258_audio_s *priv =
    (FAR struct bk7258_audio_s *)((uintptr_t)strtoul(argv[1], NULL, 16));
  FAR struct ap_buffer_s *apb;
  struct audio_msg_s msg;
  struct mq_attr attr;
  unsigned int prio;
  int msglen;

  AUD_INFO("Worker thread entry (type=%s)",
           priv->type == BK7258_AUDIO_TYPE_PLAYBACK ? "playback" : "capture");

  while (!priv->terminate)
    {
      /* Wait for messages from the message queue */

      msglen = file_mq_receive(&priv->mq, (FAR char *)&msg,
                               sizeof(msg), &prio);

      if (msglen < sizeof(struct audio_msg_s))
        {
          if (priv->terminate)
            {
              break;
            }

          AUD_ERR("Message too small: %d", msglen);
          continue;
        }

      switch (msg.msg_id)
        {
          case AUDIO_MSG_ENQUEUE:
            {
              apb = (FAR struct ap_buffer_s *)msg.u.ptr;

              if (priv->type == BK7258_AUDIO_TYPE_PLAYBACK)
                {
                  /* Playback: simulate processing time */

                  if (apb->nbytes > 0)
                    {
                      /* Simulate playback by sleeping proportional to
                       * buffer size and sample rate */

                      uint32_t duration_ms = (apb->nbytes * 1000) /
                        (priv->sample_rate * priv->channels *
                         (priv->bpsamp / 8));
                      nxsig_usleep(duration_ms * 1000);
                    }
                }
              else
                {
                  /* Capture: generate silence data */

                  if (apb->nmaxbytes > 0)
                    {
                      memset(apb->samp, 0, apb->nmaxbytes);
                      apb->nbytes = apb->nmaxbytes;
                      apb->curbyte = 0;
                      apb->flags = 0;

                      /* Simulate capture timing */

                      uint32_t duration_ms = (apb->nmaxbytes * 1000) /
                        (priv->sample_rate * priv->channels *
                         (priv->bpsamp / 8));
                      nxsig_usleep(duration_ms * 1000);
                    }
                }

              /* Dequeue the buffer back to upper half */

#ifdef CONFIG_AUDIO_MULTI_SESSION
              priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                              apb, OK, NULL);
#else
              priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                              apb, OK);
#endif
            }
            break;

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
          case AUDIO_MSG_STOP:
            {
              /* Drain remaining buffers */

              for (; ; )
                {
                  file_mq_getattr(&priv->mq, &attr);
                  if (attr.mq_curmsgs == 0)
                    {
                      break;
                    }

                  file_mq_receive(&priv->mq, (FAR char *)&msg,
                                  sizeof(msg), &prio);

                  apb = (FAR struct ap_buffer_s *)msg.u.ptr;
#ifdef CONFIG_AUDIO_MULTI_SESSION
                  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                                  apb, OK, NULL);
#else
                  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
                                  apb, OK);
#endif
                }

              priv->terminate = true;
            }
            break;
#endif

          default:
            AUD_ERR("Unknown message ID %d", msg.msg_id);
            break;
        }
    }

  /* Clean up */

  file_mq_close(&priv->mq);
  file_mq_unlink(priv->mqname);
  priv->mqname[0] = '\0';

  priv->running = false;

#ifdef CONFIG_AUDIO_MULTI_SESSION
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
#else
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
#endif

  AUD_INFO("Worker thread exit");

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_audio_playback_initialize
 *
 * Description:
 *   Initialize and register the BK7258 playback audio device as
 *   /dev/audio/pcm0p
 *
 ****************************************************************************/

int bk7258_audio_playback_initialize(void)
{
  FAR struct bk7258_audio_s *priv;
  int ret;

  AUD_INFO("Initializing playback device");

  priv = kmm_zalloc(sizeof(struct bk7258_audio_s));
  if (!priv)
    {
      AUD_ERR("Failed to allocate playback device");
      return -ENOMEM;
    }

  priv->dev.ops = &g_bk7258_playback_ops;
  priv->type = BK7258_AUDIO_TYPE_PLAYBACK;
  priv->sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
  priv->channels = BK7258_AUDIO_DEFAULT_CHANNELS;
  priv->bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
