  if (ret < 0)
    {
      bk7258_ap_record_fault(UINT32_C(0x52505400) |
                             ((uint32_t)-ret & UINT32_C(0xff)));
      bk7258_ap_heartbeat_led_write(false);
    }
#endif

  ret = kthread_create("bk7258-ap-health", 80, 2048,
