596	static int bk7258_worker_thread(int argc, FAR char **argv)
597	{
598	  FAR struct bk7258_audio_s *priv =
599	    (FAR struct bk7258_audio_s *)((uintptr_t)strtoul(argv[1], NULL, 16));
600	  FAR struct ap_buffer_s *apb;
601	  struct audio_msg_s msg;
602	  struct mq_attr attr;
603	  unsigned int prio;
604	  int msglen;
605	
606	  AUD_INFO("Worker thread entry (type=%s)",
607	           priv->type == BK7258_AUDIO_TYPE_PLAYBACK ? "playback" : "capture");
608	
609	  while (!priv->terminate)
610	    {
611	      /* Wait for messages from the message queue */
612	
613	      msglen = file_mq_receive(&priv->mq, (FAR char *)&msg,
614	                               sizeof(msg), &prio);
615	
616	      if (msglen < sizeof(struct audio_msg_s))
617	        {
618	          if (priv->terminate)
619	            {
620	              break;
621	            }
622	
623	          AUD_ERR("Message too small: %d", msglen);
624	          continue;
625	        }
626	
627	      switch (msg.msg_id)
628	        {
629	          case AUDIO_MSG_ENQUEUE:

680	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
681	          case AUDIO_MSG_STOP:
682	            {
683	              /* Drain remaining buffers */
684	
685	              for (; ; )
686	                {
687	                  file_mq_getattr(&priv->mq, &attr);
688	                  if (attr.mq_curmsgs == 0)
689	                    {
690	                      break;
691	                    }
692	
693	                  file_mq_receive(&priv->mq, (FAR char *)&msg,
694	                                  sizeof(msg), &prio);
695	
696	                  apb = (FAR struct ap_buffer_s *)msg.u.ptr;
697	#ifdef CONFIG_AUDIO_MULTI_SESSION
698	                  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
699	                                  apb, OK, NULL);
700	#else
701	                  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE,
702	                                  apb, OK);
703	#endif
704	                }
705	
706	              priv->terminate = true;
707	            }
708	            break;
709	#endif
710	
711	          default:
712	            AUD_ERR("Unknown message ID %d", msg.msg_id);
713	            break;
714	        }
715	    }
716	
717	  /* Clean up */
718	
719	  file_mq_close(&priv->mq);
720	  file_mq_unlink(priv->mqname);
721	  priv->mqname[0] = '\0';
722	
723	  priv->running = false;
724	
725	#ifdef CONFIG_AUDIO_MULTI_SESSION
726	  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
727	#else
728	  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
729	#endif

730	
731	  AUD_INFO("Worker thread exit");
732	
733	  return OK;
734	}
