int bk7258_audio_playback_initialize(void)
{
  FAR struct bk7258_audio_s *priv;
  int ret;

  syslog(LOG_INFO, "BK7258: Initializing playback device\n");

  priv = kmm_zalloc(sizeof(struct bk7258_audio_s));
  if (!priv)
    {
      syslog(LOG_ERR, "BK7258: Failed to allocate playback device\n");
      return -ENOMEM;
    }

  syslog(LOG_INFO, "BK7258: Allocated priv=%p, size=%d\n",
         priv, sizeof(struct bk7258_audio_s));

  priv->dev.ops = &g_bk7258_playback_ops;
  priv->type = BK7258_AUDIO_TYPE_PLAYBACK;
  priv->sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
  priv->channels = BK7258_AUDIO_DEFAULT_CHANNELS;
  priv->bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
  priv->gain = BK7258_AUDIO_DEFAULT_GAIN;
  priv->running = false;
  priv->terminate = false;
  priv->mqname[0] = '\0';

  syslog(LOG_INFO, "BK7258: Calling audio_register(pcm0p, %p)\n",
         &priv->dev);

  ret = audio_register("pcm0p", &priv->dev);
  if (ret < 0)
    {
      syslog(LOG_ERR, "BK7258: audio_register failed: %d\n", ret);
      kmm_free(priv);
      return ret;
    }

  syslog(LOG_INFO, "BK7258: Playback device registered OK\n");
  return OK;
}

